import { useEffect, useState } from 'react';
import { Route, RefreshCw } from 'lucide-react';
import { api } from '../lib/api';
import { usePanelData } from '../hooks/usePanelData';
import type { SlownessManifestResponse, SlownessRouteResponse } from '../types';
import { EmptyState } from './EmptyState';

/**
 * "Why is this bus slow?" — the corridor slowness decomposition card (P7.1).
 *
 * This is the question the project was founded on (June 2026). The card
 * renders, per route, the measured components with provenance: scheduled
 * in-vehicle time (GTFS), observed lateness pad (collector pool), ghost
 * no-show rate (trip ledger), and the circuity ratio (path geometry) —
 * plus the journey anchor, a planned end-to-end ride of the corridor that
 * the sum invariant pins (on-route + walk == end-to-end; on-route ==
 * GTFS segment run).
 *
 * Doctrine: coverage holes render as reasoned nulls, never fake zeros;
 * pad <= 0 is disclosed (early-departure signature), not clamped.
 */

function ProvenanceRow({
  label,
  display,
  detail,
  highlight,
}: {
  label: string;
  display: string;
  detail: string;
  highlight?: boolean;
}) {
  return (
    <div className="flex items-baseline justify-between gap-3 py-1.5 border-b border-border/50 last:border-0">
      <div className="min-w-0">
        <div className={`text-sm ${highlight ? 'font-semibold' : ''}`}>{label}</div>
        <div className="text-xs text-text-muted truncate" title={detail}>{detail}</div>
      </div>
      <div className={`text-sm tabular-nums shrink-0 ${highlight ? 'font-semibold' : ''}`}>
        {display}
      </div>
    </div>
  );
}

function renderComponent(
  comp: SlownessRouteResponse['components'][keyof SlownessRouteResponse['components']],
  format: (v: number) => string,
  reasonFallback: string
): { display: string; detail: string } {
  if (comp.value === null || comp.value === undefined) {
    return { display: '—', detail: comp.reason ?? reasonFallback };
  }
  const bits: string[] = [];
  if (comp.source) bits.push(comp.source);
  if (comp.n != null) bits.push(`n=${comp.n}`);
  return { display: format(comp.value), detail: bits.join(' · ') };
}

export default function SlownessCard() {
  const [route, setRoute] = useState<string>('36');
  // Manifest fetch stays a side-effect (it only feeds the route dropdown;
  // its failure must not block the default route's card).
  const [manifest, setManifest] = useState<SlownessManifestResponse | null>(null);
  useEffect(() => {
    api
      .slownessManifest()
      .then(setManifest)
      .catch(() => setManifest(null));
  }, []);

  // P2: route data fetch/loading/error owned by the hook, keyed on route
  // (was a cancelled-flag effect).
  const { data, error, loading, reload } = usePanelData<SlownessRouteResponse>({
    fetcher: () => api.slownessRoute(route),
    deps: [route],
  });

  const comps = data?.components;
  const anchor = data?.journey_anchor;
  const iv = comps ? renderComponent(comps.in_vehicle_min, (v) => `${v.toFixed(1)} min`, 'unmeasurable') : null;
  const pad = comps ? renderComponent(comps.pad_min, (v) => `${v >= 0 ? '+' : ''}${v.toFixed(2)} min`, 'unmeasured') : null;
  const ghost = comps ? renderComponent(comps.ghost_rate_pct, (v) => `${v.toFixed(1)}%`, 'unmeasured') : null;
  const circ = comps ? renderComponent(comps.circuity_ratio, (v) => `${v.toFixed(2)}×`, 'not flagged') : null;

  return (
    <section aria-label="Slowness decomposition">
      <div className="flex items-center justify-between gap-2 mb-2">
        <h3 className="text-sm font-semibold flex items-center gap-1.5">
          <Route className="w-4 h-4" aria-hidden /> Why is this bus slow?
        </h3>
        <button
          onClick={reload}
          className="text-text-muted hover:text-text"
          aria-label="Refresh slowness card"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      <div className="flex items-center gap-2 mb-3">
        <select
          value={route}
          onChange={(e) => setRoute(e.target.value)}
          className="text-sm rounded border border-border bg-transparent px-2 py-1"
          aria-label="Pick a route"
        >
          {(manifest?.routes ?? []).map((r) => (
            <option key={r.route_short_name} value={r.route_short_name}>
              {r.route_short_name} — {r.route_long_name}
            </option>
          ))}
        </select>
      </div>

      {error && <EmptyState reason={`Slowness card unavailable: ${error}`} />}
      {!error && loading && (
        <div role="status" aria-live="polite" className="py-4">
          <div className="text-sm text-text-muted mb-2">
            Decomposing route {route} — computing the corridor ride, this can take up to a minute on first view…
          </div>
          {[0, 1, 2, 3].map((i) => (
            <div key={i} className="h-5 rounded bg-text-muted/10 animate-pulse my-1.5" style={{ width: `${88 - i * 12}%` }} />
          ))}
        </div>
      )}
      {!error && !loading && data && comps && (
        <div>
          <div className="mb-1 text-xs text-text-muted">
            {data.route_short_name} · {data.n_trips} weekday trips · {data.service_day}
          </div>

          {iv && <ProvenanceRow label="Scheduled ride" display={iv.display} detail={iv.detail} />}
          {pad && (
            <ProvenanceRow
              label="Schedule pad (measured)"
              display={pad.display}
              detail={pad.detail}
              highlight={(comps.pad_min.value ?? 0) < 0}
            />
          )}
          {comps.pad_min.note && (
            <div className="text-xs text-amber-600 dark:text-amber-400 mb-1">{comps.pad_min.note}</div>
          )}
          {ghost && <ProvenanceRow label="Ghost no-show rate" display={ghost.display} detail={ghost.detail} />}
          {circ && (
            <ProvenanceRow
              label="Path circuity"
              display={circ.display}
              detail={circ.detail}
              highlight={(comps.circuity_ratio.value ?? 0) >= 3}
            />
          )}

          <div className="mt-3 rounded border border-border/70 p-2.5">
            <div className="text-xs font-semibold mb-1">Ride the corridor (measured plan)</div>
            {anchor?.value != null ? (
              <>
                <div className="text-sm tabular-nums">
                  {anchor.value.toFixed(1)} min end-to-end
                  {anchor.anchor_endpoint_names
                    ? ` · ${anchor.anchor_endpoint_names[0]} → ${anchor.anchor_endpoint_names[1]}`
                    : ''}
                </div>
                <div className="text-xs text-text-muted mt-0.5">
                  {anchor.on_route_min?.toFixed(1)} min on route {data.route_short_name}
                  {' + '}{anchor.walk_min?.toFixed(1)} min walk = {anchor.value.toFixed(1)} min
                  {anchor.scheduled_run_min != null
                    ? ` (GTFS segment: ${anchor.scheduled_run_min.toFixed(1)} min)`
                    : ''}
                </div>
                <div className="text-xs text-text-muted mt-0.5">
                  planned {String(Math.floor((anchor.depart_at ?? 0) / 60)).padStart(2, '0')}:
                  {String(Math.round((anchor.depart_at ?? 0) % 60)).padStart(2, '0')} departure ·{' '}
                  {anchor.route_share_pct?.toFixed(0)}% of door-to-door time on the bus
                </div>
              </>
            ) : (
              <div className="text-xs text-text-muted">{anchor?.reason ?? 'No ridable journey found'}</div>
            )}
          </div>
        </div>
      )}
    </section>
  );
}
